(function(){const s="beidaihe",a={beidaihe:"北戴河",qinhuangdao:"秦皇岛",shankhaiguan:"山海关"},d={晴:"☀️",多云:"⛅",阴:"☁️",小雨:"🌦️",中雨:"🌧️",大雨:"🌧️",暴雨:"⛈️",雷阵雨:"⛈️",小雪:"🌨️",中雪:"❄️",大雪:"❄️",雾:"🌫️",霾:"🌫️",沙尘暴:"🌪️"};function r(e){const n=d[e.now.text]||"🌤️",o=a[s]||"北戴河";return`
      <div id="weather-widget" style="
        position: fixed;
        top: 80px;
        right: 20px;
        background: rgba(255,255,255,0.95);
        backdrop-filter: blur(10px);
        border-radius: 12px;
        padding: 12px 16px;
        box-shadow: 0 4px 20px rgba(0,0,0,0.1);
        z-index: 1000;
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
        min-width: 160px;
        border: 1px solid rgba(0,0,0,0.05);
      ">
        <div style="display: flex; align-items: center; gap: 10px;">
          <span style="font-size: 28px;">${n}</span>
          <div>
            <div style="font-size: 24px; font-weight: 800; color: #0f172a; line-height: 1;">
              ${e.now.temperature}°
            </div>
            <div style="font-size: 12px; color: #64748b; margin-top: 2px;">
              ${o} · ${e.now.text}
            </div>
          </div>
        </div>
        <div style="display: flex; gap: 12px; margin-top: 8px; padding-top: 8px; border-top: 1px solid #f1f5f9;">
          <span style="font-size: 11px; color: #94a3b8;">
            💧 ${e.now.humidity||"--"}%
          </span>
          <span style="font-size: 11px; color: #94a3b8;">
            💨 ${e.now.windDirection||"--"}
          </span>
        </div>
      </div>
    `}async function i(){try{const n=await(await fetch(`/api/weather?location=${s}`)).json();if(n.success){const o=document.getElementById("weather-widget");o&&o.remove();const p=r(n);document.body.insertAdjacentHTML("beforeend",p);const t=document.getElementById("weather-widget");t.style.opacity="0",t.style.transform="translateX(20px)",t.style.transition="all 0.3s ease",setTimeout(()=>{t.style.opacity="1",t.style.transform="translateX(0)"},100)}}catch(e){console.log("天气数据获取失败:",e)}}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",i):i(),setInterval(i,1800*1e3)})();